      {id:'resume-3',firstName:'Riley',lastName:'Brooks',email:'riley.brooks@example.com',phone:'(480) 555-0116',position:'Delivery Driver',availability:'Weeknights after 4 PM',experience:'Delivery and customer-service experience; clean driving record reported.',status:'contacted',submittedAt:'2026-07-31T16:48:00-07:00',fileName:'riley-brooks-resume.pdf',source:'Public resume form',notes:[{id:'note-2',author:'Alex Morgan',text:'Phone screen requested for Tuesday.',createdAt:'2026-08-01T09:10:00-07:00'}],reviewer:'user-owner',answers:{transportation:'Yes',startDate:'Next month'}}
