  function openUserModal(id=null){if(id&&!can('users.edit'))return toast('You do not have permission to edit users.',true);if(!id&&!can('users.create'))return toast('You do not have permission to create users.',true);const list=users(),user=id?list.find(u=>u.id===id):null;const roleOptions=roles().filter(r=>!r.owner||current().role?.owner).map(r=>`<option value="${r.id}" ${user?.roleId===r.id?'selected':''}>${esc(r.name)}</option>`).join('');openModal(user?'Edit user account':'Create user account','Account administration',`<form id="userEditor"><div class="form-grid"><div><label>First name</label><input class="field" name="firstName" required value="${esc(user?.firstName||'')}"></div><div><label>Last name</label><input class="field" name="lastName" required value="${esc(user?.lastName||'')}"></div><div class="wide"><label>Email / login</label><input class="field" name="email" type="email" required value="${esc(user?.email||'')}"></div><div><label>Account type</label><select class="field" name="roleId">${roleOptions}</select></div><div><label>Restaurant position</label><input class="field" name="position" required value="${esc(user?.position||'Employee')}"></div><div><label>Status</label><select class="field" name="status"><option value="active" ${user?.status==='active'?'selected':''}>Active</option><option value="invited" ${user?.status==='invited'?'selected':''}>Invited</option><option value="suspended" ${user?.status==='suspended'?'selected':''}>Suspended</option></select></div><div><label>${user?'New password (optional)':'Temporary password'}</label><input class="field" name="password" ${user?'':'required'} value="${user?'':'Welcome123!'}"></div></div><div class="inline-warning" style="margin-top:12px">Prototype only: browser credentials are local test data. The included backend schema stores a secure password hash and server-side sessions.</div><div class="form-actions"><button type="button" class="btn btn-light" id="cancelUserEditor">Cancel</button><button class="btn btn-primary">${user?'Save changes':'Create account'}</button></div></form>`,()=>{$('cancelUserEditor').onclick=closeModal;$('userEditor').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const all=users();if(all.some(u=>u.email.toLowerCase()===data.email.toLowerCase()&&u.id!==id))return toast('That email is already assigned.',true);if(user){Object.assign(user,{firstName:data.firstName,lastName:data.lastName,displayName:`${data.firstName} ${data.lastName}`,initials:`${data.firstName[0]}${data.lastName[0]}`.toUpperCase(),email:data.email,roleId:data.roleId,position:data.position,status:data.status});if(data.password)user.password=data.password;audit('user.updated','user',user.id,{roleId:user.roleId,status:user.status})}else{all.push({id:uid('user'),email:data.email,password:data.password,firstName:data.firstName,lastName:data.lastName,displayName:`${data.firstName} ${data.lastName}`,initials:`${data.firstName[0]}${data.lastName[0]}`.toUpperCase(),roleId:data.roleId,position:data.position,status:data.status,lastLogin:null,createdAt:now(),progress:{quiz:0,flashcards:0,daily:0,certifications:0,overdue:0}});audit('user.created','user',all.at(-1).id,{roleId:data.roleId})}Auth.saveUsers(all);closeModal();renderUsers();renderOwner();toast(user?'User account updated.':'User account created.')}})}
