  function openRoleModal(){if(!can('roles.create'))return toast('You do not have permission to create account types.',true);openModal('Create account type','Role-based access control',`<form id="roleEditor"><div class="form-grid"><div><label>Account type name</label><input class="field" name="name" required placeholder="Example: Kitchen Trainer"></div><div><label>Slug</label><input class="field" name="slug" required placeholder="kitchen_trainer"></div><div class="wide"><label>Description</label><textarea class="field" name="description" required></textarea></div></div><div class="setup-divider"></div><div class="permission-groups">${permissionGroups()}</div><div class="form-actions"><button type="button" class="btn btn-light" id="cancelRoleEditor">Cancel</button><button class="btn btn-primary">Create account type</button></div></form>`,()=>{$('cancelRoleEditor').onclick=closeModal;$('roleEditor').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.currentTarget),data=Object.fromEntries(fd),permissions=fd.getAll('permissions'),list=roles();if(list.some(r=>r.slug===data.slug))return toast('That account-type slug already exists.',true);list.push({id:uid('role'),name:data.name,slug:data.slug.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_'),description:data.description,system:false,owner:false,permissions});Auth.saveRoles(list);audit('role.created','role',list.at(-1).id,{permissions});closeModal();renderRoles();renderUsers();toast('Custom account type created.')}})}
